# Get all input items from the previous node
items = _items

# Store the ecommerce rows
rows = []

for item in items:
    data = item.get("json", {})
    rows.append(data)

# Return everything as ONE item
return [
    {
        "json": {
            "rows": rows,
            "total_records": len(rows)
        }
    }
]

# Get KPI data from Code in Python1
