})

# -----------------------------
# CATEGORY SALES
# -----------------------------

for category, sales in kpi.get("Sales_By_Category", {}).items():

    dashboard.append({
        "Section": "Category Sales",
        "Metric": category,
        "Value": sales
    })

# -----------------------------
# PRODUCT SALES
# -----------------------------

for product, sales in kpi.get("Sales_By_Product", {}).items():

    dashboard.append({
        "Section": "Product Sales",
        "Metric": product,
        "Value": sales
    })

# -----------------------------
# CHANNEL SALES
# -----------------------------

for channel, sales in kpi.get("Sales_By_Channel", {}).items():

    dashboard.append({
        "Section": "Channel Sales",
        "Metric": channel,
        "Value": sales
    })

# -----------------------------
# PAYMENT SALES
# -----------------------------

for payment, sales in kpi.get("Sales_By_Payment_Method", {}).items():

    dashboard.append({
        "Section": "Payment Sales",
        "Metric": payment,
        "Value": sales
    })

# Return Excel-ready rows
return [
    {
        "json": row
    }
    for row in dashboard
]
